/** 
 * {@inheritDoc}
 */
@Override public String toString(){
  ByteArrayOutputStream streamOut = new ByteArrayOutputStream();
  PrintWriter writerOut = new PrintWriter(new EscapedWriter(new OutputStreamWriter(streamOut)));
  try {
    Printer.v().printTo(this, writerOut);
  } catch (RuntimeException e) {
    // 记录异常信息并抛出，确保调用者能够感知问题
    System.err.println("RuntimeException occurred during printTo: " + e.getMessage());
    throw e;
  }
  writerOut.flush();
  writerOut.close();
  return streamOut.toString();
}
